-- Más ejercicios para la biblioteca del box demo (ADR 0050): los derivados de halterofilia y los
-- movimientos con mancuerna de los WOD del Open, fuerza accesoria, los gimnásticos de las Girls y
-- los Heroes (anillas, cuerda, pino, pistol, sit-ups), el sled pull de HYROX, core y movilidad.
-- Los que tienen máxima en el catálogo (peso muerto sumo, hip thrust, dominada y fondo lastrados)
-- van enlazados. Idempotente: salta los que ya existen con el mismo nombre.
INSERT INTO "exercises" ("organization_id", "name", "category", "equipment", "movement_code", "section_id", "description", "coaching_points", "common_faults", "scaling", "created_by")
SELECT o."id", v."name", v."category", v."equipment"::jsonb, v."movement",
  (SELECT s."id" FROM "sections" s WHERE s."organization_id" = o."id" AND s."name" = v."section"),
  v."description", v."points", v."faults", v."scaling",
  (SELECT u."id" FROM "users" u WHERE u."email" = 'coach@demo.test')
FROM "organizations" o
CROSS JOIN (VALUES
  ('Hang power clean', 'weightlifting', '["barbell"]', NULL::text, 'CrossFit', 'Cargada desde colgado, con la barra por encima de la rodilla, recibida en rack frontal por encima de la paralela.', E'Bajar a colgado con la cadera atrás y la barra pegada al muslo.\nExtender la cadera antes de tirar con los brazos.\nCodos rápidos hacia delante en la recepción.', E'Tirar con los brazos antes de extender la cadera.\nBarra que se separa del cuerpo.\nRecibir con los codos bajos.', E'Hang muscle clean.\nPVC o barra vacía.\nMenos carga y series cortas.'),
  ('Hang power snatch', 'weightlifting', '["barbell"]', NULL::text, 'CrossFit', 'Arrancada desde colgado, con la barra por encima de la rodilla, recibida con los brazos bloqueados por encima de la paralela.', E'Agarre ancho: la barra en el pliegue de la cadera.\nBarra pegada al cuerpo en la subida.\nBloquear los brazos y estabilizar arriba.', E'Barra que se aleja hacia delante.\nBrazos que terminan en press.\nCaer con los pies demasiado abiertos.', E'Hang muscle snatch.\nPVC o barra vacía.\nDumbbell snatch.'),
  ('Hang squat clean', 'weightlifting', '["barbell"]', NULL::text, 'CrossFit', 'Cargada desde colgado recibida en sentadilla frontal completa.', E'Extender la cadera y meterse bajo la barra.\nCodos altos en la recepción.\nSalir de la sentadilla con el tronco erguido.', E'Recibir en power y luego bajar.\nCodos que caen en el fondo.\nTalones que se levantan.', E'Hang power clean más front squat.\nMenos carga.'),
  ('Snatch balance', 'weightlifting', '["barbell"]', NULL::text, 'CrossFit', 'Con la barra en la espalda y agarre de arrancada, impulso corto y bajar rápido a la sentadilla con los brazos bloqueados.', E'Impulso corto con las piernas, sin saltar.\nEmpujar contra la barra para meterse debajo.\nBloquear los brazos en el fondo.', E'Saltar hacia arriba en lugar de bajar.\nBrazos blandos en la recepción.', E'Overhead squat con pausa.\nDrop snatch con PVC.\nMenos carga.'),
  ('Ground to overhead', 'weightlifting', '["barbell"]', NULL::text, 'CrossFit', 'Llevar la barra del suelo a encima de la cabeza como se quiera: arrancada, o cargada y envión. Cuenta con los brazos bloqueados y la cadera extendida.', E'Elegir la técnica según la carga y la fatiga.\nBarra pegada al cuerpo desde el suelo.\nBloqueo completo arriba antes de bajar.', E'Espalda redonda al levantar del suelo.\nNo terminar la extensión arriba.', E'Menos carga.\nCon mancuerna (dumbbell snatch).'),
  ('Shoulder to overhead', 'weightlifting', '["barbell"]', NULL::text, 'CrossFit', 'Desde el rack frontal, llevar la barra arriba con press, push press o jerk. Cuenta con los brazos bloqueados y la barra sobre los talones.', E'Dip corto y vertical.\nLa cabeza pasa hacia delante al final.\nRespirar arriba, no abajo.', E'Arquear la lumbar.\nBarra por delante de la cabeza.', E'Push press con menos carga.\nCon mancuernas.'),
  ('Sumo deadlift high pull', 'weightlifting', '["barbell"]', NULL::text, 'CrossFit', 'Desde postura sumo y agarre estrecho, extender piernas y cadera y tirar de la barra hasta debajo de la barbilla.', E'Pies anchos y agarre entre las piernas.\nPrimero la cadera, luego los brazos.\nCodos altos, por encima de las manos.', E'Tirar solo con los brazos.\nEspalda redonda al bajar.', E'Sumo deadlift sin tirón.\nCon kettlebell.\nMenos carga.'),
  ('Dumbbell snatch', 'weightlifting', '["dumbbell"]', NULL::text, 'CrossFit', 'Con una mancuerna, del suelo a encima de la cabeza en un solo movimiento, alternando o no de brazo.', E'La mancuerna toca el suelo entre los pies.\nLa fuerza sale de la cadera.\nBrazo bloqueado y bíceps junto a la oreja arriba.', E'Espalda redonda en el suelo.\nTerminar en press en lugar de bloqueo.', E'Menos peso.\nDesde colgado (hang).'),
  ('Devil press', 'weightlifting', '["dumbbell"]', NULL::text, 'CrossFit', 'Burpee con dos mancuernas y, al subir, llevarlas del suelo a encima de la cabeza en un solo swing.', E'Pecho al suelo entre las mancuernas.\nCadera atrás y mancuernas entre las piernas.\nBloquear arriba con los bíceps junto a las orejas.', E'Espalda redonda en el swing.\nTirar con los brazos.', E'Una sola mancuerna.\nBurpee y dumbbell snatch por separado.\nMenos peso.'),
  ('Peso muerto sumo', 'strength', '["barbell"]', 'sumo_deadlift', 'CrossFit', 'Peso muerto con los pies muy abiertos y las manos por dentro de las piernas.', E'Puntas abiertas y rodillas hacia fuera.\nPecho alto y barra pegada.\nEmpujar el suelo hacia los lados.', E'Rodillas que caen hacia dentro.\nCadera que sube antes que la barra.', E'Kettlebell sumo deadlift.\nMenos carga.'),
  ('Peso muerto rumano', 'strength', '["barbell"]', NULL::text, 'CrossFit', 'De pie, bajar la barra pegada a las piernas llevando la cadera atrás con las rodillas casi rectas, y volver a subir.', E'Rodillas un poco flexionadas y fijas.\nCadera atrás y espalda neutra.\nBajar hasta notar los isquios, sin perder la curva.', E'Redondear la espalda.\nConvertirlo en sentadilla.', E'Con mancuernas o kettlebell.\nMenos recorrido.'),
  ('Hip thrust', 'strength', '["barbell"]', 'hip_thrust', NULL::text, 'Con la espalda alta apoyada en un banco y la barra sobre la cadera, subir la cadera hasta alinear tronco y muslos.', E'Pies planos y espinillas verticales arriba.\nBarbilla recogida.\nApretar los glúteos arriba un segundo.', E'Arquear la lumbar arriba.\nEmpujar con las puntas de los pies.', E'Puente de glúteo en el suelo.\nSin carga o con un disco.'),
  ('Dominada lastrada', 'strength', '["pullup_bar"]', 'weighted_pull_up', 'CrossFit', 'Dominada estricta con peso colgado de un cinturón o una mancuerna entre los pies.', E'Empezar con los brazos estirados.\nHombros activos.\nBarbilla por encima de la barra sin balanceo.', E'Balancearse para subir.\nMedia repetición.', E'Dominada estricta sin peso.\nNegativas lentas con peso.'),
  ('Fondo lastrado', 'strength', '["other"]', 'weighted_dip', 'CrossFit', 'Fondo en paralelas con peso colgado de un cinturón: bajar hasta que el hombro pase el codo y subir hasta bloquear.', E'Tronco algo adelantado.\nCodos hacia atrás, no abiertos.\nBloqueo completo arriba.', E'Poca profundidad.\nHombros que suben hacia las orejas.', E'Fondos sin peso.\nFondos con banda.\nFondos en banco.'),
  ('Good morning', 'strength', '["barbell"]', NULL::text, NULL::text, 'Con la barra en la espalda, llevar la cadera atrás e inclinar el tronco con la espalda neutra, y volver.', E'Rodillas un poco flexionadas.\nCadera atrás, no abajo.\nEspalda neutra en todo el recorrido.', E'Redondear la espalda.\nDemasiada carga.', E'Con PVC.\nMenos recorrido.'),
  ('Zancada búlgara', 'strength', '["dumbbell", "box"]', NULL::text, NULL::text, 'Sentadilla a una pierna con el pie de atrás apoyado en un banco o un cajón.', E'Pie delantero lo bastante adelantado.\nRodilla de atrás hacia el suelo.\nTronco firme.', E'Rodilla delantera que cae hacia dentro.\nEmpujar con la pierna de atrás.', E'Sin peso.\nZancada estática con los dos pies en el suelo.'),
  ('Remo con barra', 'strength', '["barbell"]', NULL::text, NULL::text, 'Con el tronco inclinado y la espalda neutra, tirar de la barra hacia el ombligo.', E'Cadera atrás y tronco a unos 45 grados.\nLlevar los codos atrás.\nBajar con control.', E'Levantar el tronco para tirar.\nEspalda redonda.', E'Remo con mancuerna.\nRing rows.'),
  ('Dumbbell thruster', 'strength', '["dumbbell"]', NULL::text, 'CrossFit', 'Sentadilla frontal con dos mancuernas en los hombros y, al subir, press hasta bloquear arriba en un solo movimiento.', E'Mancuernas apoyadas en los hombros.\nCodos altos en la sentadilla.\nLa cadera empuja el press.', E'Separar sentadilla y press.\nMancuernas que caen hacia delante.', E'Una sola mancuerna.\nMenos peso.'),
  ('Ring dip', 'gymnastics', '["rings"]', NULL::text, 'CrossFit', 'Fondo en anillas: bajar hasta que el hombro pase el codo y subir hasta bloquear los brazos.', E'Anillas pegadas al cuerpo.\nGirar las palmas hacia fuera arriba.\nControl en la bajada.', E'Anillas que se abren.\nPoca profundidad.', E'Fondos en paralelas.\nFondos con banda.\nFondos en banco.'),
  ('Ring row', 'gymnastics', '["rings"]', NULL::text, NULL::text, 'Colgado de las anillas con el cuerpo inclinado y recto, tirar hasta llevar las anillas al pecho.', E'Cuerpo recto de los talones a la cabeza.\nCodos atrás y escápulas juntas.\nCuanto más horizontal, más difícil.', E'Cadera que cae.\nTirar solo con los brazos.', E'Cuerpo más vertical.\nRodillas dobladas.'),
  ('Pistol', 'gymnastics', '["bodyweight"]', NULL::text, 'CrossFit', 'Sentadilla a una pierna con la otra estirada al frente, hasta abajo del todo y de vuelta arriba.', E'Talón de apoyo pegado al suelo.\nBrazos al frente para equilibrar.\nRodilla en la línea del pie.', E'Talón que se levanta.\nRodilla hacia dentro.\nCaer al fondo sin control.', E'Pistol a cajón.\nAgarrado a una anilla o a un poste.\nZancadas.'),
  ('Subida a la cuerda', 'gymnastics', '["other"]', NULL::text, 'CrossFit', 'Subir por la cuerda hasta tocar la marca de arriba, bloqueando la cuerda con los pies.', E'Bloquear la cuerda con los pies antes de estirar las piernas.\nSubir con las piernas, no con los brazos.\nBajar mano a mano, sin deslizar.', E'Subir solo a pulso.\nDeslizarse al bajar y quemarse las manos.', E'Practicar el bloqueo de pies desde sentado.\nSubir desde tumbado hasta de pie.\nMedia cuerda.'),
  ('Handstand walk', 'gymnastics', '["bodyweight"]', NULL::text, 'CrossFit', 'Caminar sobre las manos una distancia, normalmente en tramos de 1,5 metros.', E'Hombros abiertos y brazos bloqueados.\nAbdomen firme y cuerpo en línea.\nPasos cortos con las manos.', E'Arquear la espalda.\nPasos largos que hacen perder el equilibrio.', E'Wall walks.\nAguantar el pino contra la pared.\nToques de hombro en el pino.'),
  ('Wall walk', 'gymnastics', '["bodyweight"]', NULL::text, 'CrossFit', 'Desde boca abajo con los pies en la pared, subir los pies por la pared y acercar las manos hasta casi tocarla. Volver a bajar.', E'Cuerpo firme, sin hundir la cadera.\nManos casi en la pared arriba.\nBajar con control.', E'Arquear la lumbar.\nDejarse caer al volver.', E'Menos altura.\nPlancha con los pies en un cajón.'),
  ('Knees to elbows', 'gymnastics', '["pullup_bar"]', NULL::text, 'CrossFit', 'Desde colgado, subir las rodillas hasta tocar los codos.', E'Brazos estirados y empujar la barra hacia abajo.\nRodillas a los codos, no al pecho.\nControlar el balanceo.', E'Rodillas que no llegan.\nBalanceo sin control.', E'Knee raises.\nV-ups en el suelo.'),
  ('Sit-up', 'gymnastics', '["bodyweight"]', NULL::text, NULL::text, 'Abdominal con AbMat: de tumbado, con las manos tocando el suelo detrás de la cabeza, a sentado tocando los pies.', E'Plantas de los pies juntas o pies en el suelo.\nManos al suelo detrás de la cabeza.\nManos a los pies arriba.', E'No tocar el suelo con las manos.\nTirar del cuello.', E'Menos repeticiones.\nCrunch.'),
  ('GHD sit-up', 'gymnastics', '["other"]', NULL::text, 'CrossFit', 'En la máquina GHD, bajar el tronco hacia atrás hasta tocar el suelo con las manos y subir hasta tocar los pies.', E'Ajustar la máquina con la cadera fuera del apoyo.\nSubir estirando las rodillas.\nEmpezar con poco recorrido.', E'Demasiado volumen el primer día: riesgo de rabdomiólisis.\nTirar del cuello.', E'Bajar solo hasta la paralela.\nSit-ups con AbMat.'),
  ('L-sit', 'gymnastics', '["bodyweight"]', NULL::text, NULL::text, 'Aguantar el cuerpo con los brazos rectos, en paralelas, anillas o el suelo, y las piernas estiradas al frente a la altura de la cadera.', E'Hombros abajo, lejos de las orejas.\nPiernas juntas y rodillas bloqueadas.\nPies en punta.', E'Hombros encogidos.\nRodillas dobladas.', E'Rodillas al pecho (tuck).\nUna pierna estirada y la otra doblada.'),
  ('Walking lunge', 'gymnastics', '["bodyweight"]', NULL::text, NULL::text, 'Zancadas caminando: la rodilla de atrás roza el suelo en cada paso.', E'Paso largo y estable.\nRodilla de atrás al suelo.\nExtender la cadera al terminar cada paso.', E'Rodilla delantera hacia dentro.\nPaso corto que carga la rodilla.', E'Zancada estática.\nMenos recorrido.'),
  ('Burpee box jump over', 'gymnastics', '["box"]', NULL::text, 'CrossFit', 'Burpee de cara al cajón y, al subir, saltar al cajón o por encima hasta el otro lado.', E'Pecho al suelo de cara al cajón.\nDespegar con los dos pies.\nVale pasar por encima sin tocarlo.', E'Despegar con un pie.\nNo tocar el suelo con el pecho.', E'Pasar andando en lugar de saltar.\nCajón más bajo.'),
  ('Bar-facing burpee', 'gymnastics', '["barbell"]', NULL::text, 'CrossFit', 'Burpee de cara a la barra y salto por encima de ella con los dos pies a la vez.', E'Cuerpo paralelo a la barra.\nSaltar con los dos pies a la vez.\nNo hace falta extender arriba.', E'Despegar con un pie.\nPecho que no toca el suelo.', E'Pasar la barra andando.\nBurpee sin flexión.'),
  ('Shuttle run', 'monostructural', '["bodyweight"]', NULL::text, NULL::text, 'Carrera de ida y vuelta entre dos líneas, tocando la línea con la mano en cada cambio.', E'Bajar el centro de gravedad antes del giro.\nTocar la línea con la mano.\nArrancar con pasos cortos.', E'Girar de pie, sin frenar.\nNo tocar la línea.', E'Menos distancia por tramo.\nCaminando rápido.'),
  ('Goblet squat', 'kettlebell', '["kettlebell"]', NULL::text, NULL::text, 'Sentadilla con la kettlebell agarrada por los cuernos delante del pecho.', E'Codos por dentro de las rodillas abajo.\nPecho alto.\nTalones en el suelo.', E'Kettlebell que se aleja del pecho.\nRodillas hacia dentro.', E'Sin peso.\nSentadilla a cajón.'),
  ('Turkish get-up', 'kettlebell', '["kettlebell"]', NULL::text, NULL::text, 'Desde tumbado con la kettlebell bloqueada arriba, levantarse paso a paso hasta estar de pie y volver al suelo sin bajarla.', E'Mirar la kettlebell todo el rato.\nBrazo bloqueado y muñeca recta.\nCada paso, con calma.', E'Codo que se dobla.\nPrisa entre pasos.', E'Sin peso o con un zapato en el puño.\nSolo la primera mitad, hasta sentado.'),
  ('Kettlebell snatch', 'kettlebell', '["kettlebell"]', NULL::text, NULL::text, 'Con una mano, la kettlebell pasa entre las piernas y sube en un solo movimiento hasta bloquear arriba.', E'La fuerza sale de la cadera.\nMeter la mano para que la kettlebell no golpee el antebrazo.\nBloquear arriba con el bíceps junto a la oreja.', E'Kettlebell que golpea el antebrazo.\nTirar con el brazo.', E'Swing a una mano.\nKettlebell high pull.\nMenos peso.'),
  ('Sled pull', 'accessory', '["sled"]', NULL::text, 'HYROX', 'Arrastrar el trineo con una cuerda, mano sobre mano, hasta la línea de llegada.', E'Cadera baja y pies firmes.\nTirar con piernas, espalda y brazos.\nMano sobre mano sin parar.', E'Tirar solo con los brazos.\nEspalda redonda.', E'Menos carga.\nTramos más cortos.'),
  ('Medicine ball clean', 'accessory', '["med_ball"]', NULL::text, 'CrossFit', 'Llevar el balón medicinal del suelo al pecho y recibirlo en sentadilla completa. Enseña la cargada.', E'Balón entre los pies.\nExtensión de cadera rápida.\nRecibir con los codos debajo del balón.', E'Tirar con los brazos.\nRecibir arriba, sin sentadilla.', E'Balón más ligero.\nPor partes: peso muerto, salto y sentadilla.'),
  ('Plancha', 'accessory', '["bodyweight"]', NULL::text, NULL::text, 'Aguantar apoyado en los antebrazos y las puntas de los pies con el cuerpo recto.', E'Glúteos y abdomen apretados.\nCodos bajo los hombros.\nRespirar sin perder la posición.', E'Cadera caída o demasiado alta.\nCuello colgando.', E'Rodillas en el suelo.\nManos en un cajón.'),
  ('V-up', 'accessory', '["bodyweight"]', NULL::text, NULL::text, 'Boca arriba y estirado, subir piernas y tronco a la vez hasta tocar los pies con las manos.', E'Piernas y brazos rectos.\nSubir los dos lados a la vez.\nBajar con control hasta el hollow.', E'Doblar las piernas.\nCaer de golpe al bajar.', E'Tuck-ups con las rodillas dobladas.\nUna pierna cada vez.'),
  ('Back extension', 'accessory', '["other"]', NULL::text, NULL::text, 'En la GHD o un banco de lumbares, bajar el tronco con la espalda neutra y subir hasta alinearlo con las piernas.', E'Cadera apoyada en el borde.\nSubir con glúteos e isquios.\nArriba, cuerpo recto sin arquear.', E'Arquear la lumbar arriba.\nBalancearse.', E'Menos recorrido.\nArch hold en el suelo.'),
  ('Band pull-apart', 'accessory', '["other"]', NULL::text, NULL::text, 'Con una banda elástica delante, a la altura de los hombros y con los brazos rectos, abrirla hasta tocar el pecho.', E'Brazos rectos.\nJuntar las escápulas.\nVolver despacio.', E'Encoger los hombros.\nArquear la espalda.', E'Banda más suave.\nAgarre más ancho.'),
  ('Arch hold', 'accessory', '["bodyweight"]', NULL::text, NULL::text, 'Aguantar boca abajo con brazos y piernas estirados y separados del suelo. Es la posición contraria al hollow.', E'Glúteos apretados.\nBrazos junto a las orejas.\nMirada al suelo.', E'Doblar las rodillas.\nForzar el cuello hacia arriba.', E'Brazos al lado del cuerpo.\nSubir solo las piernas o solo los brazos.'),
  ('Couch stretch', 'mobility', '["bodyweight"]', NULL::text, NULL::text, 'Con la rodilla de atrás en el suelo junto a la pared y el empeine apoyado en ella, estirar el cuádriceps y el flexor de la cadera.', E'Glúteo apretado del lado de atrás.\nTronco erguido poco a poco.\nDos minutos por lado.', E'Arquear la lumbar.\nForzar el rango.', E'Rodilla más lejos de la pared.\nManos apoyadas delante.'),
  ('Movilidad de tobillo', 'mobility', '["bodyweight"]', NULL::text, NULL::text, 'De rodillas y con un pie delante, llevar la rodilla hacia delante sin levantar el talón.', E'Talón pegado al suelo.\nRodilla en la línea del segundo dedo.\nRitmo lento.', E'Levantar el talón.\nRodilla hacia dentro.', E'Menos recorrido.\nCon una banda en el tobillo.'),
  ('World''s greatest stretch', 'mobility', '["bodyweight"]', NULL::text, NULL::text, 'Desde zancada con las dos manos en el suelo, bajar el codo hacia el pie de delante y girar el tronco abriendo el brazo hacia arriba.', E'Pierna de atrás estirada.\nGirar desde la espalda alta.\nSeguir la mano con la mirada.', E'Hundir la cadera.\nPrisa entre posiciones.', E'Rodilla de atrás en el suelo.\nMenos giro.'),
  ('Movilidad torácica con foam roller', 'mobility', '["other"]', NULL::text, NULL::text, 'Boca arriba con el foam roller bajo la espalda alta, extender la espalda por encima del rodillo tramo a tramo.', E'Manos detrás de la cabeza.\nCostillas abajo.\nRespirar en cada posición.', E'Rodar sobre la lumbar.\nArquear desde la zona baja.', E'Con una toalla enrollada.\nMenos amplitud.'),
  ('Movilidad de muñecas', 'mobility', '["bodyweight"]', NULL::text, NULL::text, 'A cuatro patas, cargar el peso sobre las muñecas con los dedos hacia delante, hacia los lados y hacia las rodillas.', E'Cargar poco a poco.\nCodos rectos.\nAntes de pinos, front squat o halterofilia.', E'Cargar de golpe.\nForzar con dolor.', E'Menos peso sobre las manos.\nDe pie, contra la pared.')
) AS v("name", "category", "equipment", "movement", "section", "description", "points", "faults", "scaling")
WHERE o."slug" = 'demo-box'
  AND NOT EXISTS (
    SELECT 1 FROM "exercises" e WHERE e."organization_id" = o."id" AND lower(e."name") = lower(v."name")
  );
